BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('e-shikaku-q53', '1. 数学的基礎',
   '次の2×2行列 A の行列式 |A| を求めよ。
A = [[3, 4], [2, 5]]',
   NULL::text,
   '["7", "-7", "23", "-14"]',
   0, '[0]', 'single',
   '{"asked": "2×2行列の行列式(determinant)を、具体的な数値行列で計算できるかを問う問題。", "point": "行列式は ad-bc(2×2の場合)で計算し、0でなければ正則行列(逆行列を持つ)と判断できる。", "why_asked": "行列式は逆行列が存在するかどうかを判定する基本の量で、線形代数の計算問題の土台としてよく出る。", "kid": "行列式は、正方形に並んだ数字から計算する「その行列らしさを表す1つの数字」。この数字が0だと、その行列には逆行列(割り算に相当する操作)が存在しない。", "eg": "行列式は、行列に付いている「健康診断の数値」のようなもの。0でなければ「正常(逆行列あり)」、0なら「異常(逆行列なし)」とひと目でわかる。", "terms": [["行列式(determinant)", "正方行列から計算される1つの数値。|A|やdet(A)と書く"], ["正則行列(regular matrix)", "逆行列が存在する行列。行列式が0でない"], ["特異行列(singular matrix)", "逆行列が存在しない行列。行列式が0になる"]], "think": "2×2行列 [[a,b],[c,d]] の行列式は、左上×右下(a×d)から右上×左下(b×c)を引いて求める。掛ける相手を間違えたり、引き算を足し算にしたりする取り違えが起こりやすいので、どの位置の数字同士を掛けるかを図で確認するとよい。", "calc": {"steps": ["問題: A=[[3,4],[2,5]]の行列式を求める", "ステップ1: 公式|A|=ad-bcを使う。a=3,b=4,c=2,d=5", "ステップ2: ad=3×5=15", "ステップ3: bc=4×2=8", "ステップ4: 15-8=7", "答え: 7(0ではないのでAは正則行列)"], "formula": "|A| = ad - bc = 3×5 - 4×2 = 15 - 8 = 7"}, "vs": "固有値(Av=λvを満たすλ)とは別の量。行列式は行列1個から決まる1つの数値だが、固有値は複数個(この場合2個)存在しうる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"20\" y=\"20\" font-size=\"10\" fill=\"#8892a4\">行列式|A|の計算(2×2)</text><text x=\"95\" y=\"58\" font-size=\"16\" fill=\"#e8eaf0\">3</text><text x=\"160\" y=\"58\" font-size=\"16\" fill=\"#e8eaf0\">4</text><text x=\"95\" y=\"95\" font-size=\"16\" fill=\"#e8eaf0\">2</text><text x=\"160\" y=\"95\" font-size=\"16\" fill=\"#e8eaf0\">5</text><path d=\"M80 35 L75 35 L75 105 L80 105\" stroke=\"#2a2f3f\" fill=\"none\" stroke-width=\"1.5\"/><path d=\"M182 35 L187 35 L187 105 L182 105\" stroke=\"#2a2f3f\" fill=\"none\" stroke-width=\"1.5\"/><line x1=\"100\" y1=\"48\" x2=\"163\" y2=\"88\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"163\" y1=\"48\" x2=\"100\" y2=\"88\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"210\" y=\"50\" font-size=\"10\" fill=\"#60a5fa\">ad = 3×5 = 15</text><text x=\"210\" y=\"70\" font-size=\"10\" fill=\"#c9a04a\">bc = 4×2 = 8</text><text x=\"210\" y=\"95\" font-size=\"11\" fill=\"#e8eaf0\">|A| = 15 - 8 = 7</text></svg>", "opt": ["正解。ad-bc=3×5-4×2=15-8=7。0でないのでAは正則行列(逆行列を持つ)。", "ad-bcの引き算の順番をbc-adと逆にしてしまうと符号が反転し-7になる。値の大きさは合っていても符号が逆なので誤り。", "ad-bcを引き算ではなく足し算(ad+bc)で計算してしまうと15+8=23になる。行列式の定義は引き算であることに注意。", "aとc、bとdのように、掛け合わせる位置を取り違える(3×2-4×5=6-20=-14)と別の値になってしまう。対角の組み合わせを正しく取ることが重要。"]}'),

  ('e-shikaku-q54', '1. 数学的基礎',
   '次の対角行列 B の逆行列 B⁻¹ を求めよ。
B = [[2, 0], [0, 4]]',
   NULL::text,
   '["[[1/2, 0], [0, 1/4]]", "[[2, 0], [0, 4]]", "[[-2, 0], [0, -4]]", "[[1/4, 0], [0, 1/2]]"]',
   0, '[0]', 'single',
   '{"asked": "対角行列の逆行列を、具体的な数値で求められるかを問う問題。", "point": "対角行列の逆行列は、各対角成分の逆数を取るだけで求まる。", "why_asked": "逆行列は連立方程式を1回の掛け算で解く道具で、機械学習では線形回帰の正規方程式など「最適な重みを直接計算する」場面で登場するため、まず一番簡単な対角行列で感覚をつかんでおく必要がある。", "kid": "逆行列は、ある行列に掛けると「何もしなかったのと同じ」状態(単位行列)に戻してくれる行列。対角行列(斜めの並びにしか数字がない行列)なら、それぞれの数字をただの分数(逆数)に変えるだけで逆行列が作れる。", "eg": "2倍する操作の逆は1/2倍する操作、4倍する操作の逆は1/4倍する操作。対角行列の逆行列は、この「倍率を逆数にする」をそれぞれの対角成分に対してやっているだけ。", "terms": [["逆行列(inverse matrix)", "ある行列Aに掛けると単位行列Iになる行列。A⁻¹と書く"], ["単位行列(identity matrix)", "対角成分が1、それ以外が0の行列。数の1に相当する"], ["正規方程式(normal equation)", "線形回帰で最適な重みwを一発で計算する式w=(XᵀX)⁻¹Xᵀy。逆行列が登場する"]], "think": "対角行列は対角成分以外がすべて0なので、掛け算をしても各対角成分同士しか影響し合わない。そのため逆行列も、各対角成分をそのまま逆数に置き換えるだけで作れる(一般の行列のように行列式で割る計算をしなくてよい)。実際にB×B⁻¹を計算すると対角成分は2×1/2=1、4×1/4=1になり、単位行列になることで確認できる。", "calc": {"steps": ["問題: B=[[2,0],[0,4]]の逆行列を求める", "ステップ1: 対角行列の逆行列は、各対角成分の逆数を取るだけでよい", "ステップ2: 1つ目の対角成分2の逆数は1/2", "ステップ3: 2つ目の対角成分4の逆数は1/4", "答え: [[1/2,0],[0,1/4]]"], "formula": "B⁻¹ = [[1/2,0],[0,1/4]] (B×B⁻¹=単位行列Iになることで確認できる)"}, "vs": "転置行列(行と列を入れ替える操作)とは別の操作。転置は値をそのまま位置だけ動かすが、逆行列は値そのもの(この場合は逆数)を変える。", "opt": ["正解。対角行列の逆行列は各対角成分の逆数を取ればよいので、2→1/2、4→1/4になる。", "元の行列Bをそのまま書いた値。逆行列を求めず、何も操作していない状態にとどまっている。", "各成分の符号を反転させた値。逆行列は符号を変える操作ではなく、逆数(1÷元の値)を取る操作である。", "対角成分の逆数を求めるところまでは正しいが、1/2と1/4を入れる位置を入れ替えてしまっている。"]}'),

  ('e-shikaku-q55', '1. 数学的基礎',
   '次の行列 C の転置行列 Cᵀ を求めよ。
C = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]',
   NULL::text,
   '["[[1, 4, 7], [2, 5, 8], [3, 6, 9]]", "[[1, 2, 3], [4, 5, 6], [7, 8, 9]]", "[[7, 8, 9], [4, 5, 6], [1, 2, 3]]", "[[3, 2, 1], [6, 5, 4], [9, 8, 7]]"]',
   0, '[0]', 'single',
   '{"asked": "行列の転置(行と列を入れ替える操作)を、具体的な数値行列で正しく実行できるかを問う問題。", "point": "転置は行と列を入れ替えるだけで、要素の値そのものは変えない操作。", "why_asked": "誤差逆伝播法(バックプロパゲーション)では、順伝播で使った重み行列Wの転置Wᵀを使って勾配を逆向きに伝える計算が出てくるため、転置がどんな操作かを具体的に理解しておく必要がある。", "kid": "転置は、行列を対角線を軸にひっくり返して、横の並び(行)と縦の並び(列)を入れ替える操作。数字そのものは変えず、置き場所だけを変える。", "eg": "表計算ソフトで「行と列を入れ替えて貼り付け」をするイメージ。中身のデータは同じだが、横に並んでいたものが縦に並び直す。", "terms": [["転置(transpose)", "行と列を入れ替える操作。CᵀやC^Tと書く"], ["行(row)", "行列を横方向に見たまとまり"], ["列(column)", "行列を縦方向に見たまとまり"]], "think": "元の行列のi行j列にある要素は、転置後はj行i列に移る。Cの1行目[1,2,3]は転置後の1列目に、2行目[4,5,6]は転置後の2列目に、3行目[7,8,9]は転置後の3列目になる。3×3の正方行列なので行数・列数は3のまま変わらないが、各行・各列の中身の並びは入れ替わる。", "calc": {"steps": ["問題: C=[[1,2,3],[4,5,6],[7,8,9]]の転置行列Cᵀを求める", "ステップ1: 転置は元のi行j列の要素を、j行i列に置き直す操作", "ステップ2: 1行目[1,2,3]は、転置後は1列目[1,2,3]になる", "ステップ3: 2行目[4,5,6]は、転置後は2列目[4,5,6]になる", "ステップ4: 3行目[7,8,9]は、転置後は3列目[7,8,9]になる", "答え: [[1,4,7],[2,5,8],[3,6,9]]"], "formula": "(Cᵀ)のj行i列 = Cのi行j列"}, "vs": "逆行列(A⁻¹、掛けると単位行列になる行列)とは別の操作。転置は正方行列でなくても計算でき、値そのものも変えないが、逆行列は正方行列にしか(基本的には)定義されず、値も変わる。", "opt": ["正解。1行目[1,2,3]が1列目に、2行目[4,5,6]が2列目に、3行目[7,8,9]が3列目になる。", "転置の操作をせず、元の行列をそのまま書いている。各行・各列の中身が入れ替わっていない。", "行の並び順を1行目と3行目で入れ替えただけで、行と列の入れ替え(転置)にはなっていない。各行の中身自体は元のまま。", "各行の中の要素の並びを逆順にしただけで、行と列の入れ替え(転置)にはなっていない。行と行の間の関係は元のまま。"]}'),

  ('e-shikaku-q56', '1. 数学的基礎',
   '平均μ=0、標準偏差σ=1の標準正規分布の確率密度関数
f(x) = (1/√(2πσ²)) exp(-(x-μ)²/(2σ²))
について、x=0における値 f(0) に最も近いものはどれか。',
   NULL::text,
   '["約0.399", "約1.000", "約0.159", "約0.500"]',
   0, '[0]', 'single',
   '{"asked": "正規分布の確率密度関数の式に具体的な数値(μ=0, σ=1, x=0)を代入して、値を計算できるかを問う問題。", "point": "x=μの地点では指数部分が0になりexp(0)=1となるため、f(μ)=1/√(2πσ²)だけで求まる。", "why_asked": "正規分布の式は記号が多く身構えてしまいやすいが、山の頂点(x=μ)では指数部分がまるごと1になって式が単純化する。この「一番簡単な代入点」で計算できるかどうかが、式全体を怖がらずに読めるかの分かれ目になる。", "kid": "正規分布のグラフは真ん中(平均)が一番高い山の形をしている。x=0(=平均そのもの)での高さを求める問題で、指数の部分の計算が0になって消えるので、実は残りの部分の計算だけで答えが出る。", "eg": "山の頂上の高さを聞かれているようなもの。麓からの距離(x-μ)が0だと、標高を決める複雑な式の一部がまるごと「変化なし」を意味する1になり、残りのシンプルな部分だけで高さが決まる。", "terms": [["exp(x)", "eのx乗(e^x)を表す。eはネイピア数と呼ばれる約2.718の定数"], ["π", "円周率。約3.14159"], ["確率密度関数(probability density function)", "連続的な値を取る確率変数について、ある値の「出やすさ」を表す関数。面積が確率に対応する"]], "think": "式の指数部分-(x-μ)²/(2σ²)に x=0, μ=0 を代入すると、分子の(x-μ)²が(0-0)²=0になるため、指数全体が0になる。exp(0)=1(何乗もしていないので変化なし)なので、f(0)=1/√(2πσ²)×1=1/√(2π×1)=1/√(2π)を計算すればよい。√(2π)は約2.507なので、1÷2.507≈0.399となる。", "calc": {"steps": ["問題: μ=0,σ=1のとき、f(0)の値を求める", "ステップ1: 指数部分を計算する。-(x-μ)²/(2σ²) = -(0-0)²/(2×1) = 0", "ステップ2: exp(0)=1(何乗もしていないので1のまま)", "ステップ3: 残りの部分を計算する。1/√(2πσ²) = 1/√(2π×1) = 1/√(2π)", "ステップ4: √(2π)≈2.507なので、1÷2.507≈0.399", "答え: 約0.399"], "formula": "f(0) = 1/√(2π×1²) × exp(0) = 1/√(2π) ≈ 0.399"}, "vs": "確率密度の値そのものと確率を混同しないこと。f(0)≈0.399は「x=0の周辺の出やすさの高さ」であって、x=0がぴったり起こる確率(=0)ではない。確率は面積(積分)で求まる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"20\" y1=\"110\" x2=\"320\" y2=\"110\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M40 108 Q100 108 130 60 Q170 15 210 60 Q240 108 300 108\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"108\" x2=\"170\" y2=\"58\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"155\" y=\"125\" font-size=\"10\" fill=\"#8892a4\">μ=0</text><text x=\"178\" y=\"52\" font-size=\"10\" fill=\"#c9a04a\">f(0)≈0.399</text><text x=\"20\" y=\"20\" font-size=\"10\" fill=\"#8892a4\">標準正規分布(μ=0, σ=1)</text></svg>", "opt": ["正解。x=μなので指数部分は0になりexp(0)=1。1/√(2π)≈0.399になる。", "分布の頂点だから確率密度が1になるはずだと考えた値。確率密度は確率そのものではなく、値が1を超えることも1未満になることもある。", "√(2π)の√を取らずに1/(2π)を計算した値。1÷(2×3.14159)≈0.159になるが、平方根を取り忘れている。", "分布の左右で確率が半分ずつだからと、頂点の高さも0.5になると考えた値。累積確率(面積)と確率密度(高さ)を取り違えている。"]}'),

  ('e-shikaku-q57', '1. 数学的基礎',
   '確率変数Xが区間[2, 10]の一様分布に従うとき、期待値E[X]と分散V[X]の組み合わせとして正しいものはどれか。',
   NULL::text,
   '["E[X]=6, V[X]=16/3(≈5.33)", "E[X]=6, V[X]=32", "E[X]=6, V[X]=2/3(≈0.67)", "E[X]=8, V[X]=16/3(≈5.33)"]',
   0, '[0]', 'single',
   '{"asked": "区間[a,b]の一様分布について、期待値の公式(a+b)/2と分散の公式(b-a)²/12に具体的な数値を当てはめて計算できるかを問う問題。", "point": "一様分布なら期待値は区間の中点(a+b)/2、分散は(b-a)²/12で求まる。", "why_asked": "一様分布は最も単純な連続分布として、期待値・分散の公式に数値を当てはめる練習問題の定番。特に分散の公式は「2乗してから12で割る」という2段階の操作を両方正しくできるかが問われる。", "kid": "一様分布は、決まった範囲の中でどの値も同じくらい出やすい分布。範囲のちょうど真ん中の値が期待値(平均的にどのあたりに出るか)になり、範囲の広さから分散(ばらつきの大きさ)が決まる。", "eg": "2mから10mの間のどこかにランダムに矢が刺さる的をイメージする。矢が刺さりやすい場所の平均は真ん中の6m地点。的の幅(8m)が広いほど、矢の刺さる場所もばらつきやすくなる。", "terms": [["一様分布(uniform distribution)", "決まった区間[a,b]の中で、どの値も同じ確率で起こる分布"], ["期待値E[X]", "確率変数が平均的にどのあたりの値を取るかを表す量"], ["分散V[X]", "値のばらつきの大きさを表す量"]], "think": "一様分布の期待値は区間のちょうど中点になるので(a+b)/2で求まる。分散は区間の幅(b-a)を2乗してから12で割る(b-a)²/12という公式を使う。2乗を忘れたり、12で割るところを別の数で割ったりする取り違えに注意する。", "calc": {"steps": ["問題: 区間[2,10]の一様分布の期待値と分散を求める", "ステップ1: 期待値は区間の中点。E[X]=(a+b)/2=(2+10)/2=6", "ステップ2: 分散の公式(b-a)²/12を使うため、まずb-aを計算する。10-2=8", "ステップ3: 8を2乗する。8²=64", "ステップ4: 64を12で割る。64÷12=16/3≈5.33", "答え: E[X]=6, V[X]=16/3(≈5.33)"], "formula": "E[X]=(a+b)/2=6, V[X]=(b-a)²/12=64/12=16/3"}, "vs": "正規分布の分散(σ²をそのままパラメータとして与える)とは違い、一様分布の分散は区間の幅から公式で計算して求める値である。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30\" y1=\"110\" x2=\"310\" y2=\"110\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><rect x=\"70\" y=\"60\" width=\"200\" height=\"30\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"60\" x2=\"170\" y2=\"110\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"58\" y=\"125\" font-size=\"10\" fill=\"#8892a4\">a=2</text><text x=\"262\" y=\"125\" font-size=\"10\" fill=\"#8892a4\">b=10</text><text x=\"148\" y=\"130\" font-size=\"10\" fill=\"#c9a04a\">E[X]=6</text><text x=\"30\" y=\"20\" font-size=\"10\" fill=\"#8892a4\">一様分布の確率密度 f(x)=1/(b-a)</text></svg>", "opt": ["正解。E[X]=(2+10)/2=6、V[X]=(10-2)²/12=64/12=16/3≈5.33。", "期待値は合っているが、分散の計算で12で割らず2で割ってしまっている(64÷2=32)。公式の分母を取り違えている。", "期待値は合っているが、分散の計算で幅を2乗せずに12で割ってしまっている(8÷12=2/3)。2乗する手順が抜けている。", "分散は合っているが、期待値を区間の中点ではなく区間の幅(b-a=8)と取り違えている。"]}'),

  ('e-shikaku-q58', '1. 数学的基礎',
   'ある工場で作られる部品のうち5%が不良品である。検査装置は、不良品を95%の確率で正しく「不良」と判定し、良品を98%の確率で正しく「良品」と判定する(つまり良品を誤って「不良」と判定してしまう確率は2%)。ある部品が検査で「不良」と判定されたとき、実際に不良品である確率(ベイズの定理で計算)に最も近いものはどれか。',
   NULL::text,
   '["約71%", "約95%", "約5%", "約29%"]',
   0, '[0]', 'single',
   '{"asked": "ベイズの定理を使って、検査で「不良」と判定されたという条件のもとで、実際に不良品である確率(事後確率)を計算する問題。", "point": "ベイズの定理では「事前確率×尤度」を不良品・良品それぞれで計算し、その比で事後確率を求める。", "why_asked": "「検査の精度が95%だから、不良判定が出れば95%の確率で不良品」という直感的な誤解を、実際の数値計算で正すための定番論点。E資格でも確率モデルのパラメータ推定の土台として、ベイズの定理の数値計算は繰り返し問われる。", "kid": "不良品はもともと100個中5個しかない。検査で「不良」と出た部品の中には、①本当に不良品で正しく不良と出た部品と、②良品なのに間違って不良と出てしまった部品の2種類が混ざっている。", "eg": "火災報知器が鳴ったからといって必ず火事とは限らないのと似ている。火事がそもそも滅多に起きないなら、「誤作動で鳴った」回数の方が「本当の火事で鳴った」回数より多くなることがある。", "terms": [["事前確率(prior)", "検査結果を見る前の、もともとの不良品の割合(この場合5%)"], ["尤度(likelihood)", "不良品(または良品)であるときに、検査で「不良」と判定される確率"], ["事後確率(posterior)", "検査結果(「不良」判定)を見た後で計算し直した、実際に不良品である確率"]], "think": "検査の精度(尤度)だけを見ると不良品だと思い込みやすいが、不良品はもともと少数派なので、良品からの誤判定の件数が本当の不良品の件数を上回ってしまうことがある。事前確率(もともとの割合)と尤度(検査の当たりやすさ)を両方掛け合わせてから比べる必要がある。", "calc": {"steps": ["問題: 1000個のうち不良品は5%=50個、良品は950個とする", "ステップ1: 不良品50個のうち95%が正しく不良と判定される。50×0.95=47.5個", "ステップ2: 良品950個のうち2%が誤って不良と判定される。950×0.02=19個", "ステップ3: 不良と判定された部品の合計は47.5+19=66.5個", "ステップ4: そのうち本当に不良なのは47.5個なので、47.5÷66.5≈0.714", "答え: 約71%"], "formula": "P(不良|不良判定) = 47.5 ÷ (47.5+19) = 47.5/66.5 ≈ 0.714 → 約71%"}, "vs": "検査が不良品を正しく「不良」と判定する確率(感度、95%)と、「不良」と判定された部品が実際に不良品である確率(事後確率、約71%)は向きが逆の数値であり、混同しやすい。", "opt": ["正解。47.5÷(47.5+19)≈0.714で、約71%になる。", "検査が不良品を正しく「不良」と判定する確率(感度)であり、「不良」と判定された部品が実際に不良品である確率とは向きが逆の数値。", "不良品のもともとの割合(事前確率)であり、検査結果を反映した後の確率(事後確率)ではない。", "1から答えを引いた大まかな見積もりで、正しいベイズの定理の計算結果ではない。"]}'),

  ('e-shikaku-q59', '1. 数学的基礎',
   '次の5組のデータ (X, Y) について、共分散Cov(X,Y)を求めよ(データ数nで割る定義を用いる)。
(X,Y) = (1,2), (2,4), (3,5), (4,4), (5,5)',
   NULL::text,
   '["1.2", "6", "1.5", "13.2"]',
   0, '[0]', 'single',
   '{"asked": "5組の小さなデータから、共分散を定義どおりに手計算できるかを問う問題。", "point": "共分散は各データの(X-平均)×(Y-平均)を全部足してデータ数で割ることで求まる。", "why_asked": "共分散は相関係数やPCA(主成分分析)など多くの手法の土台になる量だが、公式を暗記するだけだと符号や割り算を見落としやすいので、実際に小さいデータで手を動かして確かめておく価値が高い。", "kid": "共分散は「XとYが一緒に大きくなったり小さくなったりする傾向」を1つの数字にしたもの。Xが平均より大きいときにYも平均より大きい、という組み合わせが多いほどプラスの大きな値になる。", "eg": "身長と体重のように「片方が大きいと、もう片方も大きくなりやすい」関係があるとき、共分散はプラスの値になる。逆に「片方が大きいと、もう片方は小さくなりやすい」関係だとマイナスの値になる。", "terms": [["共分散(covariance)", "2つの変数が一緒にどう変動するかを表す量。Cov(X,Y)と書く"], ["平均(mean)", "データを全部足してデータ数で割った値"], ["偏差(deviation)", "各データから平均を引いた値。平均からどれだけ離れているか"]], "think": "共分散は、各データについて「Xの偏差×Yの偏差」を計算し、それを全部足してからデータ数で割ることで求める。Xが平均より大きいときにYも平均より大きければ(偏差の積がプラス)、共分散を押し上げる方向に働く。", "calc": {"steps": ["問題: (1,2),(2,4),(3,5),(4,4),(5,5)の5組データの共分散を求める(nで割る)", "ステップ1: Xの平均は(1+2+3+4+5)/5=3、Yの平均は(2+4+5+4+5)/5=4", "ステップ2: 各組の(X-平均)×(Y-平均)を計算する。(-2)×(-2)=4, (-1)×0=0, 0×1=0, 1×0=0, 2×1=2", "ステップ3: これらを合計する。4+0+0+0+2=6", "ステップ4: データ数5で割る。6÷5=1.2", "答え: 1.2"], "formula": "Cov(X,Y) = (1/n)Σ(x_i-x̄)(y_i-ȳ) = 6/5 = 1.2"}, "vs": "相関係数(共分散を標準偏差の積で割って-1〜1に正規化した量)とは別物。共分散の値そのものはデータの単位に依存するため、大きさだけで関係の強さを比べることはできない。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"40\" y1=\"20\" x2=\"40\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"40\" y1=\"120\" x2=\"320\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"180\" y1=\"20\" x2=\"180\" y2=\"120\" stroke=\"#c9a04a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><line x1=\"40\" y1=\"60\" x2=\"320\" y2=\"60\" stroke=\"#c9a04a\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/><circle cx=\"80\" cy=\"100\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"130\" cy=\"60\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"180\" cy=\"40\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"230\" cy=\"60\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"280\" cy=\"40\" r=\"3\" fill=\"#e8eaf0\"/><text x=\"185\" y=\"15\" font-size=\"10\" fill=\"#c9a04a\">x̄=3, ȳ=4</text><text x=\"20\" y=\"18\" font-size=\"10\" fill=\"#8892a4\">Y</text><text x=\"300\" y=\"135\" font-size=\"10\" fill=\"#8892a4\">X</text></svg>", "opt": ["正解。偏差の積の合計6をデータ数5で割ると1.2になる。", "偏差の積の合計6をデータ数で割らず、そのまま答えにしている。共分散は合計をデータ数で割った平均であることを忘れている。", "データ数5ではなくn-1=4で割った値(不偏共分散に近い考え方)。この問題ではnで割る定義を使うよう指定されている。", "XとYの平均をそれぞれ引かずに、XとYをそのまま掛けて足した値(ΣXY/n=66/5=13.2)。平均を引く手順が抜けている。"]}'),

  ('e-shikaku-q60', '1. 数学的基礎',
   '共分散Cov(X,Y)=6、Xの標準偏差σx=3、Yの標準偏差σy=4であるとき、相関係数rを求めよ。',
   NULL::text,
   '["0.5", "約0.86", "約0.04", "2.0"]',
   0, '[0]', 'single',
   '{"asked": "共分散と2つの標準偏差から、相関係数を公式どおりに計算できるかを問う問題。", "point": "相関係数は共分散を2つの標準偏差の積で割ることで求まる。", "why_asked": "共分散はデータの単位によって値の大きさが変わってしまうため、単位に依存しない-1〜1の指標にする相関係数の計算は、共分散との関係を含めて頻出の論点になる。", "kid": "相関係数は、共分散という「単位によって大きさが変わってしまう数字」を、標準偏差で割ることで「-1〜1の間の、単位に関係なく比べられる数字」に変換したもの。", "eg": "共分散は「cmで測った身長」と「kgで測った体重」のように、単位が違うと値の大きさも変わってしまう。標準偏差の積で割ることで、単位のものさしを揃えて、どんなデータ同士でも同じ基準で関係の強さを比べられるようにしている。", "terms": [["相関係数(correlation coefficient)", "2つの変数の関係の強さを-1〜1で表す指標。r(または相関係数ρ)と書く"], ["標準偏差(standard deviation)", "分散の平方根。データのばらつきを元の単位で表した量"], ["正規化(normalization)", "値をある基準に合わせて、比べやすい範囲に変換すること"]], "think": "相関係数は、共分散を「Xの標準偏差×Yの標準偏差」で割ることで求める。分母を足し算にしてしまったり、標準偏差の代わりに分散(標準偏差の2乗)を使ってしまったりする取り違えに注意する。", "calc": {"steps": ["問題: Cov(X,Y)=6, σx=3, σy=4から相関係数rを求める", "ステップ1: 相関係数は共分散を標準偏差の積で割って求める", "ステップ2: 標準偏差の積を計算する。σx×σy=3×4=12", "ステップ3: 共分散を標準偏差の積で割る。6÷12=0.5", "答え: 0.5"], "formula": "r = Cov(X,Y) / (σx × σy) = 6/12 = 0.5"}, "vs": "共分散(単位に依存し、値の範囲に制限がない)と相関係数(単位に依存せず、必ず-1〜1に収まる)は別の量。共分散を標準偏差で正規化したものが相関係数である。", "opt": ["正解。共分散6を標準偏差の積12(=3×4)で割ると0.5になる。", "標準偏差の積(掛け算)ではなく、標準偏差の和(足し算)で割ってしまっている(6÷(3+4)≈0.86)。分母の計算方法を取り違えている。", "標準偏差ではなく分散(標準偏差の2乗)の積で割ってしまっている(6÷(9×16)≈0.04)。標準偏差と分散を混同している。", "分子と分母を逆にして計算してしまっている(12÷6=2.0)。相関係数は必ず-1〜1の範囲に収まるはずなので、この時点でもおかしいと気づける。"]}'),

  ('e-shikaku-q61', '1. 数学的基礎',
   'ある事象が起こる確率が0.25であるとき、その事象の自己情報量(self-information、単位はビット)を求めよ。',
   NULL::text,
   '["2ビット", "4ビット", "0.25ビット", "0.5ビット"]',
   0, '[0]', 'single',
   '{"asked": "確率の値から、自己情報量(-log2(p))を具体的に計算できるかを問う問題。", "point": "自己情報量は-log2(確率)で計算し、確率が小さいほど値が大きくなる。", "why_asked": "自己情報量はシャノンのエントロピーやクロスエントロピー損失の計算の土台になる量で、「起こりにくい事象ほど情報量が大きい」という直感を、実際にlog2の計算で確かめられるかが問われる。", "kid": "自己情報量は「その出来事が起きたと知って、どれくらい驚いたか(意外だったか)」を数字にしたもの。めったに起きないことほど、起きたと分かったときの情報量(驚き)は大きくなる。", "eg": "天気予報で「明日は必ず晴れます(確率100%)」と言われても驚かないので情報量はほぼ0。逆に「明日は隕石が降ります(確率0.001%のようなレアな出来事)」と言われたらとても驚くので情報量は大きくなる。", "terms": [["自己情報量(self-information)", "ある事象が起きたときに得られる情報量。起こりにくい事象ほど値が大きい"], ["log2", "2を底とする対数。「2を何乗すればその数になるか」を表す"], ["ビット(bit)", "情報量の単位。2択(コイン投げ1回分)の情報が1ビット"]], "think": "自己情報量は-log2(p)で計算する。p=0.25は1/4であり、1/4=2の-2乗(2^-2)と書き直せるので、log2(2^-2)=-2となり、マイナスをつけると2になる。「pを2の何乗の形に書き直せるか」を考えると、log2の計算が暗算しやすくなる。", "calc": {"steps": ["問題: 確率p=0.25の事象の自己情報量を求める(単位: ビット)", "ステップ1: 自己情報量は-log2(p)で計算する", "ステップ2: p=0.25=1/4=2の-2乗(2^-2)と書き直せる", "ステップ3: log2(2^-2)=-2なので、-log2(0.25)=-(-2)=2", "答え: 2ビット"], "formula": "I(x) = -log2(p) = -log2(0.25) = -log2(2^-2) = 2 [ビット]"}, "vs": "シャノンのエントロピー(H=-Σp_i log2(p_i))と混同しやすいが、エントロピーは複数の事象の自己情報量を確率で重み付けして平均した値であり、自己情報量は1つの事象1回分の値である。", "opt": ["正解。0.25=1/4=2^-2なので、-log2(0.25)=2ビットになる。", "確率0.25の逆数1/0.25=4を、そのままビット数と取り違えている。log2の計算をせず逆数を取っただけの値。", "確率の値0.25を、そのまま情報量の値として使ってしまっている。自己情報量はpそのものではなく-log2(p)で計算する。", "log2の計算を途中で誤り、本来2になるところを半分の値にしてしまっている。"]}'),

  ('e-shikaku-q62', '1. 数学的基礎',
   '次の4個の標本データから、不偏分散(n-1で割る分散)を求めよ。
データ: 2, 4, 6, 8',
   NULL::text,
   '["6.67", "5.00", "20.00", "10.00"]',
   0, '[0]', 'single',
   '{"asked": "標本データから、n-1で割る不偏分散を具体的に計算できるかを問う問題。", "point": "不偏分散は偏差平方和をnではなくn-1で割ることで、母分散の過小評価を補正する。", "why_asked": "確率モデルのパラメータ推定の基本として、標本から母集団の分散を推定するときに「なぜn-1で割るのか」という理由も含めて、E資格では単なる公式暗記でなく理解を問われやすい。", "kid": "手元にある一部のデータ(標本)から、本当の(母集団全体の)ばらつきを推定したい。単純にデータ数nで割ると、ばらつきを少なめに見積もってしまう癖があるので、1つ少ないn-1で割って埋め合わせをする。", "eg": "標本平均は、手元のデータに一番近くなるように計算された「その場しのぎの平均」なので、標本平均を使った偏差はどうしても本当の(母平均からの)ばらつきより小さめに出てしまう。n-1で割るのは、その小さめに出てしまう分を割り増しして埋め合わせる調整だとイメージするとよい。", "terms": [["不偏分散(unbiased variance)", "標本から母分散を推定するときに使う、n-1で割る分散"], ["自由度(degrees of freedom)", "データのうち自由に動ける個数。標本平均を使うと1つ分の制約が生まれ、自由度がn-1になる"], ["標本平均(sample mean)", "手元のデータから計算した平均。母平均そのものではなく、その推定値"]], "think": "標本平均を使って偏差(データ-平均)を計算すると、偏差の合計は必ず0になるという制約が生まれる。この制約のせいで、実質的に自由に動けるデータの個数はn個ではなくn-1個になる(自由度が1つ減る)。そのため、単純にnで割ると母分散を少なめに見積もってしまうので、n-1で割って補正する。", "calc": {"steps": ["問題: データ2,4,6,8の不偏分散を求める", "ステップ1: 平均を求める。(2+4+6+8)/4=5", "ステップ2: 各データと平均の差を2乗する。(2-5)²=9, (4-5)²=1, (6-5)²=1, (8-5)²=9", "ステップ3: 2乗した値を合計する(偏差平方和)。9+1+1+9=20", "ステップ4: データ数4から1を引いた3で割る。20÷3≈6.67", "答え: 約6.67"], "formula": "s² = Σ(x_i-x̄)² / (n-1) = 20/3 ≈ 6.67"}, "vs": "母分散(nで割る、この場合20÷4=5)と不偏分散(n-1で割る、この場合約6.67)は別の値。標本から母集団全体のばらつきを推定するときは、不偏分散(n-1で割る方)を使う。", "opt": ["正解。偏差平方和20をn-1=3で割ると約6.67になる。", "偏差平方和20を、n-1ではなくデータ数そのままのn=4で割ってしまっている(母分散の計算方法)。", "2乗した値を合計しただけで、データ数で割る手順が抜けている(偏差平方和そのもの)。", "偏差平方和20を、n-1=3ではなくn-2=2で割ってしまっている。割る数を1つ多く引きすぎている。"]}'),

  ('e-shikaku-q63', '1. 数学的基礎',
   '自然言語処理の埋め込みベクトル(embedding)において、2つの単語ベクトル a=(1,2), b=(2,1) のコサイン類似度を求めよ。',
   NULL::text,
   '["0.8", "4", "0.16", "約0.44"]',
   0, '[0]', 'single',
   '{"asked": "2つのベクトルの内積とL2ノルムから、コサイン類似度を具体的に計算できるかを問う問題。", "point": "コサイン類似度は内積をベクトルの長さ(L2ノルム)の積で割ることで求まる。", "why_asked": "自然言語処理では単語や文をベクトル(埋め込みベクトル)として表し、その「意味の近さ」をコサイン類似度で測ることが多い。内積だけでなくベクトルの長さで正規化する手順まで含めて計算できるかが問われる。", "kid": "コサイン類似度は、2つの矢印(ベクトル)がどれくらい同じ向きを向いているかを表す数字。ベクトルの「向き」だけを見たいので、矢印の長さの違いを打ち消すために、内積を2つの矢印の長さで割っている。", "eg": "2人が地図の上でどの方角を指差しているかを比べるイメージ。指の長さ(矢印の長さ)がバラバラでも、向いている方角がほぼ同じなら似ていると判定したい。そのために、長さの影響を割り算で取り除く。", "terms": [["コサイン類似度(cosine similarity)", "2つのベクトルの向きがどれだけ近いかを-1〜1で表す指標。1に近いほど向きが近い"], ["内積(dot product)", "対応する成分同士を掛けて、全部足し合わせたもの"], ["L2ノルム(L2 norm)", "ベクトルの長さ。各成分を2乗して足し、平方根を取って求める"]], "think": "コサイン類似度は、まず2つのベクトルの内積を計算し、それを2つのベクトルのL2ノルム(長さ)の積で割ることで求める。ノルムを求めるときに平方根を取り忘れたり、内積を求めただけで割り算をせずに終えたりする取り違えに注意する。", "calc": {"steps": ["問題: ベクトルa=(1,2)とb=(2,1)のコサイン類似度を求める", "ステップ1: 内積を計算する。a・b=1×2+2×1=2+2=4", "ステップ2: aのL2ノルム(長さ)を計算する。|a|=√(1²+2²)=√5", "ステップ3: bのL2ノルムを計算する。|b|=√(2²+1²)=√5", "ステップ4: 内積をノルムの積で割る。4÷(√5×√5)=4÷5=0.8", "答え: 0.8"], "formula": "cos θ = (a・b) / (|a||b|) = 4 / (√5×√5) = 4/5 = 0.8"}, "vs": "アダマール積(成分同士をそのまま掛けて、結果もベクトルのまま残る演算)や固有値(正方行列にしか定義されない量)とは別物。コサイン類似度は内積とノルムから計算する、1つのスカラー値である。", "opt": ["正解。内積4をノルムの積√5×√5=5で割ると0.8になる。", "内積を計算しただけで、ノルム(ベクトルの長さ)で割る手順が抜けている。", "ノルムを求めるときに平方根を取らず、各成分の2乗和(1²+2²=5)をそのままノルムとして使ってしまい、4÷(5×5)=0.16になっている。", "ノルムを√(成分の2乗和)ではなく成分の単純な合計(1+2=3、2+1=3)で計算してしまい、4÷(3×3)≈0.44になっている。"]}'),

  ('e-shikaku-q64', '1. 数学的基礎',
   '確率変数Xの分散がV[X]=4であるとき、Y=3X+5の分散V[Y]を求めよ。',
   NULL::text,
   '["36", "12", "41", "9"]',
   0, '[0]', 'single',
   '{"asked": "分散の性質V[aX+b]=a²V[X]を使って、定数倍・定数加算をしたときの分散を計算できるかを問う問題。", "point": "分散はV[aX+b]=a²V[X]で計算し、定数bを足しても分散は変わらず、係数aは2乗されて効いてくる。", "why_asked": "データの標準化(平均を引いて標準偏差で割る操作)や損失関数のスケーリングなど、機械学習の随所で「定数倍・定数加算が分散にどう効くか」を正しく扱う必要があるため、性質そのものを計算で確認しておく価値が高い。", "kid": "全部のデータに同じ数を足しても、データの散らばり方(ばらつき)は変わらない。ただの位置move(平行移動)だから。でも全部のデータを何倍かすると、散らばり方もその倍率の2乗だけ広がる。", "eg": "クラス全員のテストの点数に一律5点のボーナスを足しても、点数のばらつき方(誰が上位で誰が下位かの差)は変わらない。でも全員の点数を3倍にすると、もともと10点差だった2人の差は30点差に広がり、ばらつきはぐっと大きくなる。", "terms": [["分散(variance)", "データや確率変数の値のばらつきの大きさを表す量。V[X]と書く"], ["線形変換(linear transformation)", "aX+bのように、定数倍と定数加算だけで作られる変換"], ["係数(coefficient)", "変数に掛けられる定数。ここではaにあたる3"]], "think": "分散はデータの「散らばり方」を測る量なので、全体を同じだけ平行移動させる定数bを足しても散らばり方自体は変わらない。一方、全体をa倍すると、データ同士の差(散らばりの元になる部分)もa倍になり、それを2乗して平均する分散はa²倍になる。", "calc": {"steps": ["問題: V[X]=4のとき、Y=3X+5の分散V[Y]を求める", "ステップ1: 分散の性質V[aX+b]=a²V[X]を使う。定数bを足してもばらつきは変わらない", "ステップ2: 係数a=3を2乗する。3²=9", "ステップ3: 9×4=36", "答え: 36"], "formula": "V[aX+b] = a²V[X] = 3²×4 = 36"}, "vs": "期待値の性質E[aX+b]=aE[X]+bとは異なり、分散の性質V[aX+b]=a²V[X]には定数bが登場しない(平行移動はばらつきに影響しない)点に注意する。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"20\" y1=\"115\" x2=\"320\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M60 113 Q90 113 100 90 Q110 68 120 90 Q130 113 160 113\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"65\" y=\"58\" font-size=\"10\" fill=\"#8892a4\">X (V[X]=4)</text><path d=\"M150 113 Q200 113 220 60 Q240 15 260 60 Q280 113 320 113\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"210\" y=\"12\" font-size=\"10\" fill=\"#60a5fa\">Y=3X+5 (V[Y]=36)</text></svg>", "opt": ["正解。V[aX+b]=a²V[X]なので、3²×4=36になる。", "係数aを2乗せず、そのまま掛けてしまっている(3×4=12)。分散では係数が2乗される点が抜けている。", "係数を2乗した上に、さらに定数項5をそのまま足してしまっている(9×4+5=41)。分散には定数項bが登場しない。", "係数の効果を無視し、定数項5をそのまま足しただけになっている(4+5=9)。分散は係数の2乗倍で変わり、定数を足しても変わらないことを反映できていない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'e-shikaku'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('e-shikaku-b-q43', '1. 数学的基礎',
   'ある工場で3日間、稼働時間x(時間)と生産数y(個、100個単位の相対値)を記録したところ x=(1,2,3)、y=(2,1,3) だった。このデータの分散共分散行列の対角成分(各変数の分散)と非対角成分(共分散)を求めるとどうなるか。',
   NULL::text,
   '["対角成分(分散)はどちらも約0.67、非対角成分(共分散)は約0.33になる。", "対角成分(分散)はどちらも約0.33、非対角成分(共分散)は約0.67になる。", "対角成分(分散)はどちらも1、非対角成分(共分散)は0.5になる。", "対角成分(分散)はどちらも2、非対角成分(共分散)は1になる。"]',
   0, '[0]', 'single',
   '{"asked": "2変数の小さいデータから、分散共分散行列の対角成分(分散)と非対角成分(共分散)を実際に計算する。", "point": "対角成分は各変数自身の分散、非対角成分は2変数の共分散。", "why_asked": "PCAをはじめ多変量解析の出発点になる行列で、対角成分と非対角成分がそれぞれ何を表すかを区別できているかが問われる。", "kid": "分散共分散行列は「それぞれの変数のばらつき具合」と「2つの変数が一緒に動く度合い」を1枚の表にまとめたもの。", "eg": "クラス全員の身長のばらつきと体重のばらつきを表の対角線に、身長と体重が一緒に大きくなる度合いを表の隅に書き込むようなもの。", "terms": [["分散共分散行列", "複数の変数の分散(対角成分)と共分散(非対角成分)をまとめて並べた表"], ["共分散", "2つの変数が同じ方向に動くか逆方向に動くかを表す量。プラスなら同じ方向、マイナスなら逆方向"], ["対角成分", "行列の左上から右下に並ぶ、行番号と列番号が同じ位置の成分"]], "think": "分散は「その変数だけの自分自身とのばらつき」、共分散は「2つの変数を組にしたときに一緒に動く度合い」。分散共分散行列は、対角成分に各変数の分散、非対角成分に変数の組み合わせごとの共分散を並べたもの。", "calc": {"steps": ["問題: 3つのデータでx=(1,2,3)、y=(2,1,3)とする", "ステップ1: 平均を求める。x̄=(1+2+3)÷3=2、ȳ=(2+1+3)÷3=2", "ステップ2: 平均との差(偏差)を求める。xの偏差=(-1,0,1)、yの偏差=(0,-1,1)", "ステップ3: 分散を求める(偏差を2乗して平均)。Var(x)=((-1)²+0²+1²)÷3=2/3≈0.67、Var(y)=(0²+(-1)²+1²)÷3=2/3≈0.67", "ステップ4: 共分散を求める(偏差同士の積を平均)。Cov(x,y)=((-1)×0+0×(-1)+1×1)÷3=1/3≈0.33", "答え: 対角成分(分散)は約0.67、非対角成分(共分散)は約0.33"], "formula": "Var(x)=Σ(xᵢ-x̄)²÷n, Cov(x,y)=Σ(xᵢ-x̄)(yᵢ-ȳ)÷n"}, "vs": "対角成分(分散)は偏差を2乗するので必ず0以上になるが、非対角成分(共分散)はプラスにもマイナスにもなる。マイナスなら2つの変数が逆方向に動く関係を表す。", "opt": ["正解。x̄=ȳ=2から偏差を出し、分散2/3≈0.67、共分散1/3≈0.33が求まる。", "分散と共分散の値の組が入れ替わった値。実際に計算すると分散のほうが約0.67で共分散より大きい。", "偏差の2乗和・積の和を3(サンプル数)で割らず2で割った場合に近い値で、正しい分散・共分散の計算とは異なる。", "偏差の2乗和・積の和をそのまま(nで割らずに)使った値で、平均を取る手順が抜けている。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">分散共分散行列の構造(2変数)</text><g transform=\"translate(110,28)\"><rect x=\"0\" y=\"0\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"30\" y=\"34\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">Var(x)</text><rect x=\"60\" y=\"0\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><text x=\"90\" y=\"34\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">Cov(x,y)</text><rect x=\"0\" y=\"60\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><text x=\"30\" y=\"94\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">Cov(x,y)</text><rect x=\"60\" y=\"60\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"90\" y=\"94\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">Var(y)</text></g><circle cx=\"40\" cy=\"132\" r=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"50\" y=\"136\" fill=\"#8892a4\" font-size=\"9\">対角成分=分散</text><circle cx=\"200\" cy=\"132\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><text x=\"210\" y=\"136\" fill=\"#8892a4\" font-size=\"9\">非対角成分=共分散</text></svg>"}'),

  ('e-shikaku-b-q44', '1. 数学的基礎',
   '主成分分析(PCA)は、元のデータの分散共分散行列を固有値分解し、固有値が最大の固有ベクトルの方向を第一主成分として選ぶ。このように「分散が最大になる方向」を新しい軸に選ぶのはなぜか。',
   NULL::text,
   '["データの散らばり(分散)が最大になる方向を軸に選べば、少ない軸でも元の情報を多く残せ、圧縮しても損失を抑えられるから。", "データの散らばり(分散)が最小になる方向を軸に選べば、ノイズの影響を最も抑えられ、圧縮しても情報の損失を抑えられるから。", "元のデータの平均値に一番近い方向を軸に選べば、外れ値の影響を受けにくくなり、圧縮しても情報の損失を抑えられるから。", "元の変数の数をそのまま保ち各軸を回転させずに並べ替えれば、圧縮しなくても計算コストを大きく減らせるから。"]',
   0, '[0]', 'single',
   '{"asked": "PCAが分散共分散行列の固有値が最大の固有ベクトルを第一主成分の方向に選ぶ理由。", "point": "データが一番バラついている方向に軸を取るほど、少ない軸で元の情報を多く残せる。", "why_asked": "PCAを「なんとなく次元を減らす手法」で終わらせず、固有値分解との数理的なつながりまで理解しているかを問う定番論点。", "kid": "データが横に広く散らばっているなら、その横方向を新しい物差しにすれば、1本の物差しだけでもデータの様子がよく分かる、という発想。", "eg": "集合写真を撮るとき、みんなが一番横に広がっている向きにカメラを構えれば、1枚の写真(1本の軸)でも全員の位置関係がよく分かるのと同じ考え方。", "terms": [["主成分", "元の複数の変数を組み合わせて作る、新しい合成変数の軸"], ["固有ベクトル・固有値", "分散共分散行列に対してAv=λvを満たすv(方向)とλ(その方向の分散の大きさ)の組。λが大きい方向ほどデータが広く散らばっている"], ["寄与率", "各主成分がデータ全体の分散のうちどれだけを説明しているかの割合"]], "think": "分散共分散行列の固有値λは「その固有ベクトルの方向にデータを射影したときの分散の大きさ」を表す。分散が大きい方向ほど、その1本の軸だけでデータ同士の違い(情報)をよく区別できるため、固有値が最大の固有ベクトルを第一主成分に選ぶと、少ない軸数でも情報の損失を抑えて次元を圧縮できる。", "vs": "固有値分解そのものは正方行列(共分散行列)に対する分解であり、SVD(データ行列に直接使える一般化された分解)とは適用対象が異なる。PCAの実装ではどちらの経路で計算しても同じ主成分が得られる。", "opt": ["正解。分散が最大の方向ほど1本の軸でデータの違いをよく説明できるため、情報の損失を抑えて次元を圧縮できる。", "分散が最小の方向を選ぶと、データ同士がその軸上でほとんど区別できなくなり、むしろ情報の損失が大きくなる。", "外れ値への頑健さではなく、データの散らばりの大きさを基準に軸を選ぶ手法であり、平均への近さは基準に使っていない。", "PCAは新しい軸(主成分)へ座標を変換して次元を減らす手法であり、軸を回転させずに元の変数をそのまま並べ替えるものではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">分散が最大の方向を第一主成分に選ぶ</text><g><circle cx=\"60\" cy=\"100\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"82\" cy=\"90\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"96\" cy=\"95\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"114\" cy=\"78\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"132\" cy=\"82\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"146\" cy=\"65\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"164\" cy=\"70\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"178\" cy=\"55\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"196\" cy=\"58\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"214\" cy=\"42\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"228\" cy=\"48\" r=\"3\" fill=\"#e8eaf0\"/><circle cx=\"242\" cy=\"32\" r=\"3\" fill=\"#e8eaf0\"/></g><line x1=\"48\" y1=\"108\" x2=\"256\" y2=\"26\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"170\" y=\"130\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">第一主成分(分散が最大の方向)</text><line x1=\"132\" y1=\"55\" x2=\"162\" y2=\"90\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/><text x=\"270\" y=\"70\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">第二主成分</text></svg>"}'),

  ('e-shikaku-b-q45', '1. 数学的基礎',
   '母集団の標準偏差がσ=8であるとき、標本平均の標準誤差SE=σ/√Nは、標本サイズN=4のときとN=16のときでそれぞれいくらになるか。',
   NULL::text,
   '["N=4のときSEは4、N=16のときSEは2になり、標本サイズを4倍にするとSEは半分になる。", "N=4のときSEは4、N=16のときSEは1になり、標本サイズを4倍にするとSEは4分の1になる。", "N=4のときSEは8、N=16のときSEも8になり、標本サイズを増やしてもSEは変化しない。", "N=4のときSEは2、N=16のときSEは4になり、標本サイズを大きくするとSEも大きくなる。"]',
   0, '[0]', 'single',
   '{"asked": "標準誤差SE=σ/√Nを具体的な数値に当てはめ、標本サイズを増やすとSEがどう変化するかを計算する。", "point": "標本サイズNを4倍にすると、SEは√4=2分の1になる。", "why_asked": "「標本を増やせばブレが減る」という感覚を、1/√Nという具体的な減り方として数値で確認させる定番論点。", "kid": "標本平均の標準誤差は、標本の数を増やすほど小さくなる(ブレが減る)が、その減り方は「増やした数と同じ割合」ではなく「増やした数の平方根の分だけ」というゆっくりしたペースになる。", "eg": "同じアンケートを4人に聞くより16人に聞いたほうが平均の当てになる度合いは上がるが、16人は4人の4倍なのに、ブレの小ささはちょうど4倍にはならず2倍(√4倍)止まりという、じわじわ効いてくる感じ。", "terms": [["標準誤差(SE)", "標本平均が真の母平均からどれくらいばらつくかを表す量。σ/√Nで計算する"], ["√(平方根)", "2乗すると元の数になる数。√4=2、√16=4"]], "think": "標準誤差はσ(母集団のばらつき)をそのまま使うのではなく、√Nで割って小さくする。Nが大きくなるほど√Nも大きくなるのでSEは小さくなるが、N自体を割るわけではないため、SEの縮み方はNに比例するより緩やかになる。", "calc": {"steps": ["問題: σ=8、N=4のときとN=16のときのSE=σ/√Nを求める", "ステップ1: N=4のとき、√4=2", "ステップ2: SE=8÷2=4", "ステップ3: N=16のとき、√16=4", "ステップ4: SE=8÷4=2", "答え: N=4でSEは4、N=16でSEは2(標本サイズを4倍にするとSEは半分)"], "formula": "SE = σ ÷ √N"}, "vs": "母集団の標準偏差σそのものは標本サイズを増やしても変わらない。小さくなるのは「標本平均」のばらつきであるSEのほうであり、この違いを混同しないようにする。", "opt": ["正解。SE=8÷2=4(N=4)、SE=8÷4=2(N=16)で、標本サイズを4倍にするとSEは半分(1/√4)になる。", "標本サイズNをそのまま分母に使い、8÷4=2ではなく8÷16=0.5に近い計算をした場合の値で、√Nで割る計算とは異なる。", "σをそのままSEとして使っており、標本サイズによってSEが変化する部分の計算(÷√N)が行われていない。", "標本サイズを大きくするほどSEが大きくなるという、実際とは逆方向の変化になっている。"]}'),

  ('e-shikaku-b-q46', '1. 数学的基礎',
   'あるコールセンターには1時間あたり平均4件のクレームが入り、1時間あたりのクレーム件数Xはポアソン分布に従うとする。このときのクレーム件数の分散Var(X)はいくらか。',
   NULL::text,
   '["4。ポアソン分布では期待値(平均)と分散が両方ともλに等しくなるため、平均が4ならば分散も4になる。", "2。ポアソン分布は分散が平均の半分になる関係があるとされ、平均4の半分の2になるという計算による。", "16。ポアソン分布は分散が平均の2乗になる関係があるとされ、4を2乗した16になるという計算による。", "この情報だけでは分散は求められず、クレーム件数のばらつきを表す別のデータが追加で必要である。"]',
   0, '[0]', 'single',
   '{"asked": "ポアソン分布に従う件数の期待値(平均)から、分散を求める。", "point": "ポアソン分布では期待値と分散がどちらもλ(パラメータ)に一致する。", "why_asked": "「一定時間内に稀な事象が起こる回数」を表すポアソン分布は、期待値と分散が同じ値になるという特徴的な性質を持ち、他の分布(正規分布など)との使い分けの決め手として問われる。", "kid": "ポアソン分布は「平均で何回起きるか」を1つの数(λ、ラムダ)だけで決められる分布で、そのλがそのまま平均にも分散にもなる、という珍しい性質を持っている。", "eg": "1時間に平均4件しか起きない珍しい出来事(クレーム・事故・受信メールの急な集中など)の起こり方を数えるときに使う分布で、「平均が分かればばらつきの大きさも同じ数だけ分かってしまう」という省エネな性質。", "terms": [["ポアソン分布", "一定時間・一定範囲内に、稀な事象が平均λ回起こるときの発生回数を表す確率分布"], ["λ(ラムダ)", "ポアソン分布のパラメータ。単位時間あたりに事象が起こる平均回数を表す"]], "think": "ポアソン分布はパラメータλ1つだけで形が決まる分布で、期待値E(X)=λ、分散Var(X)=λという性質を持つ。今回は平均が4件(λ=4)と分かっているので、分散もそのまま4になる。", "vs": "二項分布は分散がnp(1-p)で期待値npより必ず小さくなるのに対し、ポアソン分布は分散と期待値がぴったり一致する点が特徴的な違い。", "opt": ["正解。ポアソン分布は期待値と分散がどちらもλに等しくなるため、平均4ならば分散も4になる。", "分散が平均の半分になるという関係はポアソン分布には成り立たず、実際には期待値と同じ値になる。", "分散が平均の2乗になるという関係はポアソン分布には成り立たず、実際には期待値と同じ値になる。", "ポアソン分布は期待値(λ)が分かれば分散もλとしてそのまま定まるため、追加のデータがなくても分散は計算できる。"]}'),

  ('e-shikaku-b-q47', '1. 数学的基礎',
   'ある工場には生産ラインA・B・Cがあり、全体の生産量に占める割合はそれぞれ40%・35%・25%、各ラインの不良率はそれぞれ2%・3%・5%である。工場全体で見たときの不良率(全体の期待値)を求めるとどうなるか。',
   NULL::text,
   '["約3.1%。各ラインの生産量の割合を重みとして、それぞれの不良率に掛けて足し合わせた値になる。", "約3.3%。3つのラインの不良率2%・3%・5%を、生産量の割合を考えずに単純に平均した値である。", "5%。3つのラインのうち最も不良率が高いラインの値を、そのまま工場全体の不良率として使った値である。", "10%。各ラインの不良率2%・3%・5%を、割合で重み付けせずにそのまま足し合わせた値である。"]',
   0, '[0]', 'single',
   '{"asked": "ライン別の生産割合と不良率から、全確率の法則を使って工場全体の不良率(条件付き期待値の重み付き合計)を求める。", "point": "「割合(重み)×それぞれの不良率」を全部足すなら全確率の法則。", "why_asked": "「場合分け(ライン)ごとの確率」を、その場合分けが起こる割合で重み付けして足し合わせるという全確率の法則・条件付き期待値の考え方は、混合分布やアンサンブル学習の理解の土台になる。", "kid": "3つのラインそれぞれで「どれくらい作っているか」と「どれくらい不良品が出るか」をかけ算して、それを全部足し合わせると、工場全体で見たときの不良率が出せる。", "eg": "3つのお店(生産量の割合が違う)がそれぞれ違う確率でハズレくじを混ぜているとき、街全体で見たときのハズレ率を知りたければ、お店ごとの規模とハズレ率をかけ算して合計するのと同じ考え方。", "terms": [["全確率の法則", "起こりうる場合分け(条件)ごとの確率を、その場合分けが起こる割合で重み付けして足し合わせると、全体の確率が求まるという法則"], ["条件付き期待値", "ある条件(このラインで作られた、など)のもとでの期待値。ここでは各ラインの不良率がそれにあたる"]], "think": "工場全体の不良率は、各ラインの不良率をそのまま平均するのではなく、各ラインがどれだけの割合を生産しているかで重み付けしてから足し合わせる必要がある。これは「場合分けごとの確率×その場合分けが起こる割合」を全部足すという全確率の法則そのもの。", "calc": {"steps": ["問題: 生産割合A=0.40, B=0.35, C=0.25 / 不良率A=0.02, B=0.03, C=0.05", "ステップ1: ラインAの寄与 = 0.40 × 0.02 = 0.008", "ステップ2: ラインBの寄与 = 0.35 × 0.03 = 0.0105", "ステップ3: ラインCの寄与 = 0.25 × 0.05 = 0.0125", "ステップ4: 全部足す = 0.008 + 0.0105 + 0.0125 = 0.031", "答え: 工場全体の不良率は約3.1%"], "formula": "全体の不良率 = Σ(各ラインの割合 × 各ラインの不良率)"}, "vs": "単純平均(2%・3%・5%をそのまま3で割る)は、各ラインの生産量が同じ場合にしか正しくならない。生産割合が違う今回は、割合による重み付けが必須。", "opt": ["正解。0.40×0.02+0.35×0.03+0.25×0.05=0.031で、約3.1%になる。", "生産割合による重み付けを行わず、3つの不良率をそのまま単純平均(2+3+5を3で割る)した値である。", "最も不良率が高いラインの値をそのまま使っており、他のラインの生産割合や不良率が反映されていない。", "生産割合による重み付けを行わず、3つの不良率の数値をそのまま足し合わせた値である。"]}'),

  ('e-shikaku-b-q48', '1. 数学的基礎',
   '2値の確率変数X、YはともにP(X=0)=P(X=1)=0.5、P(Y=0)=P(Y=1)=0.5で、常にX=Yとなる(一方が分かればもう一方も完全に分かる)とする。同時分布はP(X=0,Y=0)=0.5、P(X=1,Y=1)=0.5、P(X=0,Y=1)=P(X=1,Y=0)=0である。相互情報量 I(X;Y) = ΣP(x,y)log2(P(x,y)/(P(x)P(y))) (P=0の項は0として扱う)を計算するといくつになるか。',
   NULL::text,
   '["1(ビット)。Yを知ればXが完全に分かる関係なので、相互情報量はXの不確実性H(X)そのものと同じ1になる。", "0.5(ビット)。同時確率P(X=0,Y=0)=0.5の値を、そのまま相互情報量として使った値である。", "0(ビット)。XとYは別々の確率変数として定義されているので、相互情報量は常に0になるという考え方に基づく値である。", "2(ビット)。X、Yそれぞれが取りうる値の種類数2と2を、単純にかけ合わせた値である。"]',
   0, '[0]', 'single',
   '{"asked": "小さな同時分布の表から、相互情報量I(X;Y)を定義式にそって実際に計算する。", "point": "Yを知ればXが完全に分かるなら、I(X;Y)はH(X)と同じ値になる。", "why_asked": "相互情報量を概念(Yを知ることで減るXの不確実性)としてだけでなく、同時分布の表から実際に手を動かして計算できるかを問う。X=Yという極端な例で、I(X;Y)=H(X)=H(Y)という関係を確認させる定番の題材。", "kid": "XとYが常に同じ値になる(Yを見ればXが必ず分かる)という一番強い関係のとき、相互情報量はXそのものの「わからなさ」の量とぴったり同じになる。", "eg": "双子が必ず同じ色の服を着てくると分かっているとき、片方の服の色(Y)を見れば、もう片方(X)の色も完全に言い当てられる。このときの「情報のありがたみ」は、Xの色を当てる元々の難しさとちょうど同じだけある、というイメージ。", "terms": [["log2(対数、底2)", "2を何乗するとその数になるかを表す。log2(2)=1、2進数の情報量(ビット)を測るときに使う"], ["ビット", "情報量の単位。log2を使って測った量に付く単位"]], "think": "同時確率が0の(X=0,Y=1)と(X=1,Y=0)の項は0として無視できる。残る(X=0,Y=0)と(X=1,Y=1)はどちらもP(x,y)=0.5、P(x)P(y)=0.25なので、比は0.5÷0.25=2、log2(2)=1。それぞれ0.5×1=0.5を2つ足して合計1になる。これはXの不確実性H(X)=1(ビット)とちょうど同じ値で、Yを知ればXの不確実性が完全に(1ビット分)なくなることを表している。", "calc": {"steps": ["問題: P(X=0,Y=0)=0.5, P(X=1,Y=1)=0.5, 残り2項は0。P(X=0)=P(X=1)=P(Y=0)=P(Y=1)=0.5", "ステップ1: (X=0,Y=0)の項 : P(x,y)/(P(x)P(y)) = 0.5/(0.5×0.5) = 0.5/0.25 = 2、log2(2) = 1", "ステップ2: その項の寄与 = 0.5 × 1 = 0.5", "ステップ3: (X=1,Y=1)の項も同じ計算で寄与 = 0.5", "ステップ4: P=0の2項は0として無視し、0.5+0.5を合計する", "答え: I(X;Y) = 0.5 + 0.5 = 1(ビット)"], "formula": "I(X;Y) = Σ P(x,y) log2(P(x,y) ÷ (P(x)P(y)))"}, "vs": "相互情報量はI(X;Y)=H(X)-H(X|Y)という関係で条件付きエントロピーと結びついている。今回のようにYを知ればXが完全に分かる(H(X|Y)=0)場合、I(X;Y)はH(X)とそのまま一致する。", "opt": ["正解。P=0の2項を除いた2つの項がそれぞれ0.5×log2(2)=0.5になり、合計1(ビット)になる。", "同時確率P(X=0,Y=0)の値0.5を、log2の計算をせずにそのまま相互情報量として使ってしまっている。", "XとYには「常に同じ値になる」という強い関係があるため、相互情報量は0にはならない。", "相互情報量はXとYが取りうる値の種類数のかけ算ではなく、同時分布と周辺分布の比のlog2を重み付けして足す値である。"]}'),

  ('e-shikaku-b-q49', '1. 数学的基礎',
   'ベクトルv=(3, -4, 0, 2)について、L0ノルム(0でない要素の個数)とL∞ノルム(各成分の絶対値のうち最大のもの)をそれぞれ求めるとどうなるか。',
   NULL::text,
   '["L0ノルムは3、L∞ノルムは4。0でない要素は3,-4,2の3個で、絶対値の最大は|-4|=4である。", "L0ノルムは4、L∞ノルムは4。0の要素も含めた全要素の個数4を、そのままL0ノルムとして使った値である。", "L0ノルムは3、L∞ノルムは9。各成分の絶対値の合計3+4+0+2=9を、L∞ノルムとして使った値である。", "L0ノルムは9、L∞ノルムは3。各成分の絶対値の合計をL0ノルム、0でない要素の個数をL∞ノルムとして使った値である。"]',
   0, '[0]', 'single',
   '{"asked": "L1・L2ノルムの発展として、L0ノルムとL∞ノルムを具体的なベクトルで計算する。", "point": "L0は0でない要素の個数、L∞は成分の絶対値の最大値。", "why_asked": "L1・L2ノルムだけでなく、Lpノルムを一般化・極端化したL0(スパース性そのものを数える)・L∞(最大値だけを見る)も、正則化やロバスト性の議論で登場する。", "kid": "L0ノルムは「0じゃない成分がいくつあるか」を数えるだけの物差し、L∞ノルムは「一番大きい成分の絶対値だけ」を見る物差し。", "eg": "L0ノルムは「カバンの中身のうち、空じゃないポケットがいくつあるか」を数えるようなもの。L∞ノルムは「一番重い荷物1つだけ」に注目するようなもの。", "terms": [["Lpノルム", "各成分をp乗して足し、1/p乗するという形で一般化したノルム。p=1がL1、p=2がL2にあたる"], ["L0ノルム", "0でない成分の個数を数える(Lpノルムの定義そのものではなく、極限的に「個数を数える」ものとして使われる)"], ["L∞ノルム", "各成分の絶対値のうち最大のものを取る(pを無限大に近づけた極限にあたる)"]], "think": "L1ノルムは絶対値の和、L2ノルムは2乗和の平方根だった。L0ノルムはそれとは別に「0でない成分の個数」を数える指標で、スパース性(どれだけの成分が0になっているか)をそのまま測れる。L∞ノルムは全成分のうち絶対値が一番大きいものだけを見る指標。", "calc": {"steps": ["問題: v = (3, -4, 0, 2)", "ステップ1: 0でない成分を数える。3, -4, 2の3個が0でない → L0ノルム = 3", "ステップ2: 各成分の絶対値を並べる。|3|=3, |-4|=4, |0|=0, |2|=2", "ステップ3: そのうち最大のものを選ぶ。3, 4, 0, 2の中で最大は4", "答え: L0ノルム=3、L∞ノルム=4"], "formula": "L0ノルム = #{i : vᵢ≠0}, L∞ノルム = max(|v₁|,|v₂|,...,|vₙ|)"}, "vs": "L1正則化(Lasso)は本来L0ノルム(0でない重みの個数)を減らしたいが、L0ノルムは扱いにくい(微分できない・組合せ的)ため、代わりに扱いやすいL1ノルムを使ってスパース性に近い効果を出している。", "opt": ["正解。0でない成分は3個(L0=3)、絶対値の最大は|-4|=4(L∞=4)。", "0の要素も数に入れた全要素数(4個)をL0ノルムとして使っており、「0でない」という条件を反映できていない。", "各成分の絶対値の合計(L1ノルムにあたる計算)をL∞ノルムとして使っており、最大値を取る計算になっていない。", "L0ノルムとL∞ノルムの定義(個数を数えるか、最大値を取るか)が入れ替わった値になっている。"]}'),

  ('e-shikaku-b-q50', '1. 数学的基礎',
   '5行3列(m=5, n=3)の行列Aを特異値分解してA=UΣVᵀの形にするとき、U・Σ・Vᵀのそれぞれの行列サイズの組み合わせとして正しいものはどれか。',
   NULL::text,
   '["Uは5×5、Σは5×3、Vᵀは3×3になる。", "Uは3×3、Σは5×3、Vᵀは5×5になる。", "Uは5×5、Σは3×3、Vᵀは3×3になる。", "Uは5×3、Σは5×5、Vᵀは3×3になる。"]',
   0, '[0]', 'single',
   '{"asked": "m×n行列AをA=UΣVᵀに分解するとき、U・Σ・Vᵀそれぞれの行列サイズを求める。", "point": "Uはm×m、Σはm×n、Vᵀはn×nになる。", "why_asked": "SVDは概念(正方でなくても使える分解)だけでなく、分解後の各行列のサイズを具体的な数値で求められるかが実装レベルで問われる。", "kid": "元の表(行列)が縦5行・横3列だとすると、分解してできる3つの表は、それぞれ「5×5」「5×3」「3×3」というサイズになる。", "eg": "5人分×3科目のテスト結果の表を分解すると、「5人同士の関係を表す5×5の表」「対角線に強さを並べた5×3の表」「3科目同士の関係を表す3×3の表」の3つに分かれるようなもの。", "terms": [["U(左特異ベクトル)", "元の行列Aの行(5人分)の空間に対応する、m×mの正方行列"], ["Σ(特異値行列)", "対角成分に特異値(大きさを表す非負の数)を並べた、m×nの行列(対角成分以外は0)"], ["Vᵀ(右特異ベクトルの転置)", "元の行列Aの列(3科目分)の空間に対応する、n×nの正方行列"]], "think": "AはUの列ベクトル(m個)とVᵀの行ベクトル(n個)を、Σの対角成分(特異値)で重み付けして組み合わせた形になっている。行の数m個ぶんの情報を持つUはm×m、列の数n個ぶんの情報を持つVᵀはn×n、AそのものとサイズをそろえるΣはm×nになる。", "calc": {"steps": ["問題: A は5行3列なので m=5, n=3", "ステップ1: U は行(m個)に対応する正方行列 → 5×5", "ステップ2: Σ は A とサイズをそろえる行列(対角成分だけが特異値) → 5×3", "ステップ3: Vᵀ は列(n個)に対応する正方行列 → 3×3", "答え: U=5×5, Σ=5×3, Vᵀ=3×3"], "formula": "A(m×n) = U(m×m) Σ(m×n) Vᵀ(n×n)"}, "vs": "固有値分解A=PΛP⁻¹は正方行列にしか使えないため、Pは常にAと同じサイズの正方行列になる。SVDはAが正方でなくてもよいため、UとVᵀのサイズがAの行数・列数それぞれに応じて別々に決まる点が固有値分解と異なる。", "opt": ["正解。UはAの行数5に対応する5×5、ΣはAと同じ5×3、VᵀはAの列数3に対応する3×3になる。", "UとVᵀのサイズが入れ替わった値。実際にはUがAの行数(5)、VᵀがAの列数(3)に対応する。", "ΣのサイズをAとそろえず、n×n(3×3)にしてしまっている。ΣはAと同じ5×3になる。", "UをAと同じ5×3にしてしまっており、Uは正方行列(5×5)になるという点が反映されていない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"14\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">A = U Σ Vᵀ の行列サイズ対応(m=5, n=3)</text><g transform=\"translate(15,45)\"><rect x=\"0\" y=\"0\" width=\"30\" height=\"50\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/><text x=\"15\" y=\"66\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">A</text><text x=\"15\" y=\"78\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">5×3</text></g><text x=\"60\" y=\"76\" fill=\"#8892a4\" font-size=\"13\" text-anchor=\"middle\">=</text><g transform=\"translate(75,20)\"><rect x=\"0\" y=\"0\" width=\"50\" height=\"50\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"25\" y=\"66\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">U</text><text x=\"25\" y=\"78\" fill=\"#60a5fa\" font-size=\"8\" text-anchor=\"middle\">5×5</text></g><text x=\"140\" y=\"51\" fill=\"#8892a4\" font-size=\"13\" text-anchor=\"middle\">×</text><g transform=\"translate(155,20)\"><rect x=\"0\" y=\"0\" width=\"30\" height=\"50\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"0\" x2=\"30\" y2=\"50\" stroke=\"#c9a04a\" stroke-width=\"0.5\" stroke-dasharray=\"2,2\"/><text x=\"15\" y=\"66\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">Σ</text><text x=\"15\" y=\"78\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">5×3</text></g><text x=\"200\" y=\"51\" fill=\"#8892a4\" font-size=\"13\" text-anchor=\"middle\">×</text><g transform=\"translate(215,40)\"><rect x=\"0\" y=\"0\" width=\"30\" height=\"30\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><text x=\"15\" y=\"46\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">Vᵀ</text><text x=\"15\" y=\"58\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">3×3</text></g><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">Uは行(m)対応、Vᵀは列(n)対応、Σはmとnの両方を橋渡し</text></svg>"}'),

  ('e-shikaku-b-q51', '1. 数学的基礎',
   '母集団の分布がコインの表裏のように偏った形であっても、そこから取り出した標本の「標本平均」を何度も計算してヒストグラムを作ると、標本サイズを大きくするにつれてその分布はどんな形に近づいていくか(中心極限定理)。',
   NULL::text,
   '["元の母集団の分布の形によらず、標本サイズが大きくなるほど標本平均の分布は正規分布に近づいていく。", "元の母集団の分布が正規分布であるときに限り、標本サイズを大きくすると標本平均の分布も正規分布に近づいていく。", "元の母集団の分布の形によらず、標本サイズを大きくすると標本平均の分布は母集団の分布と同じ形にどんどん近づいていく。", "元の母集団の分布の形によらず、標本サイズを大きくすると標本平均の分布はより広がった一様分布に近づいていく。"]',
   0, '[0]', 'single',
   '{"asked": "母集団の分布の形によらず、標本平均の分布が標本サイズを大きくするとどんな形に近づいていくか。", "point": "元の分布がどんな形でも、標本平均の分布は正規分布に近づく。", "why_asked": "統計的検定・信頼区間の多くが「標本平均は正規分布に従う」という前提の上に成り立っており、その前提を保証しているのが中心極限定理であるため。ミニバッチ学習で少数サンプルの平均勾配を使う発想にも、似た「平均を取ると安定する」という感覚がつながる。", "kid": "元のデータがどんな形(表裏だけの偏った分布でも)をしていても、そこから何人分かを取り出して平均を計算する、という作業をたくさん繰り返すと、その平均値たちの分布はだんだん見慣れた山型(正規分布)に近づいていく、という性質。", "eg": "コイン投げ(表か裏かの2択)の結果だけを見るとカクカクした分布だが、「10回投げた表の割合」を何セットも計算して集めると、その割合の分布はだんだん滑らかな山型に近づいていく、というイメージ。", "terms": [["中心極限定理", "母集団の分布の形によらず、標本平均の分布が標本サイズを大きくすると正規分布に近づいていくという定理"], ["標本平均の分布", "同じ母集団から標本を何度も取り直して平均を計算したときの、その平均値たちが作る分布"]], "think": "個々のデータ1つ1つは母集団の偏った分布のままだが、「何個かのデータの平均」という操作を挟むと、極端に大きい値と極端に小さい値が打ち消し合いやすくなる。この打ち消し合いの効果が標本サイズを大きくするほど強くなり、平均値の分布は元の形によらずベルの形(正規分布)に近づいていく。", "vs": "大数の法則は「標本平均が真の値に近づいていく」という点(位置)についての法則であるのに対し、中心極限定理は「標本平均の分布の形が正規分布に近づく」という点(形)についての定理であり、問うている対象が異なる。", "opt": ["正解。元の分布の形によらず、標本平均の分布は標本サイズが大きくなるほど正規分布に近づく。", "元の分布が正規分布である必要はなく、コインの表裏のような偏った分布からでも標本平均の分布は正規分布に近づく。", "標本平均の分布が近づいていくのは母集団の分布そのものの形ではなく、正規分布という決まった形である。", "標本サイズを大きくすると標本平均の分布はむしろ山型(正規分布)に集約されていき、平らな一様分布には近づかない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">標本サイズを増やすと標本平均の分布は正規分布に近づく</text><text x=\"70\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">標本サイズ小</text><g transform=\"translate(30,40)\" fill=\"none\" stroke=\"#c47070\"><rect x=\"0\" y=\"55\" width=\"14\" height=\"10\"/><rect x=\"16\" y=\"20\" width=\"14\" height=\"45\"/><rect x=\"32\" y=\"45\" width=\"14\" height=\"20\"/><rect x=\"48\" y=\"10\" width=\"14\" height=\"55\"/><rect x=\"64\" y=\"35\" width=\"14\" height=\"30\"/><rect x=\"80\" y=\"50\" width=\"14\" height=\"15\"/></g><text x=\"250\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">標本サイズ大</text><path d=\"M195,105 Q210,30 250,30 Q290,30 305,105\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><line x1=\"190\" y1=\"105\" x2=\"310\" y2=\"105\" stroke=\"#2a2f3f\"/><line x1=\"20\" y1=\"105\" x2=\"110\" y2=\"105\" stroke=\"#2a2f3f\"/><text x=\"250\" y=\"122\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">滑らかな正規分布に近づく</text></svg>"}'),

  ('e-shikaku-b-q52', '1. 数学的基礎',
   'MAP推定は、尤度(データからの情報)と事前分布(データを見る前の想定)をかけ合わせた事後分布を最大化するパラメータを求める。データの量が少ないとき、事前分布を「強く」(特定の値のまわりに強く集中させて)設定すると、MAP推定値はどうなるか。',
   NULL::text,
   '["事前分布を強く設定するほど、MAP推定値は事前分布が示す値に引き寄せられ、データ(尤度)だけを見た最尤推定の値から離れやすくなる。", "事前分布を強く設定するほど、MAP推定値は常に最尤推定の値と完全に一致するようになり、事前分布の影響は事後分布の計算から消える。", "事前分布を弱く(分散を大きく)設定するほど、MAP推定値は事前分布が示す値に強く引き寄せられ、データの情報はほとんど反映されなくなる。", "事前分布の強さはMAP推定値の計算結果に影響を与えず、どれだけ強くしても弱くしても常に同じ推定値が得られる。"]',
   0, '[0]', 'single',
   '{"asked": "事前分布を強く(または弱く)設定すると、MAP推定の結果がどう変わるか。", "point": "事前分布を強くするほど、MAP推定値は事前分布の示す値に引き寄せられる。", "why_asked": "MAP推定は最尤推定に事前分布という「重し」を足したものであり、その重しの強さが結果にどう効くかを直感で理解しているかが、正則化(L2正則化がガウス事前分布に対応するなど)の理解にもつながる。", "kid": "MAP推定は「データだけを見た答え」と「もともとの思い込み(事前分布)」を綱引きさせて答えを決める方法。思い込みを強くするほど、データが少しくらい違う方向を示していても、答えはもともとの思い込みの側に引っ張られやすくなる。", "eg": "友達の性格について「絶対にこういう人だ」という強い思い込みがあると、少しくらい意外な行動を見ても評価があまり変わらない。逆に思い込みが弱ければ、少しの行動ですぐ評価が変わる、というのに近い。", "terms": [["事前分布", "データを見る前に、パラメータについてあらかじめ想定しておく確率分布"], ["MAP推定(最大事後確率推定)", "事後分布(尤度×事前分布に比例)を最大化するパラメータの推定方法"]], "think": "事後分布は尤度と事前分布の積に比例する。事前分布を特定の値のまわりに強く集中させる(分散を小さくする)ほど、その値から外れたパラメータの事前確率が急激に小さくなるため、たとえ尤度(データ)が別の値を支持していても、積である事後分布のピークは事前分布側に引き寄せられやすくなる。データの量が多くなれば尤度の影響が相対的に強まり、事前分布の影響は薄れていく。", "vs": "最尤推定(MLE)は尤度だけを最大化しデータの情報のみを使うのに対し、MAP推定は事前分布という追加情報を掛け合わせる点が異なる。事前分布を「一様(どの値も同じくらいありえる)」にすると、MAP推定はMLEと一致する。", "opt": ["正解。事前分布を強くするほど、MAP推定値は事前分布側に引き寄せられ、データだけを見た最尤推定の値から離れやすくなる。", "事前分布を強く設定するほど事前分布の影響が消えるという説明は逆で、実際には強くするほど事前分布の影響は大きくなる。", "事前分布を強くしたときの効果と弱くしたときの効果が入れ替わっている。データに強く引き寄せられるのは事前分布を弱くした場合である。", "事前分布の強さ(分散の大きさ)を変えると事後分布のピークの位置は変わるため、MAP推定値は事前分布の強さに応じて変化する。"]}'),

  ('e-shikaku-b-q53', '1. 数学的基礎',
   '2値エントロピー H(p) = -p log2(p) - (1-p) log2(1-p) を、p=0.5のときとp=0.1のときでそれぞれ計算すると、どちらが大きくなるか、またおおよその値はどうなるか。',
   NULL::text,
   '["p=0.5のときが大きく、H(0.5)=1(ビット)、H(0.1)は約0.47(ビット)になる。", "p=0.1のときが大きく、H(0.1)は約1.5(ビット)、H(0.5)は1(ビット)になる。", "p=0.5のときが大きいのは同じだが、値が入れ替わりH(0.5)は約0.47(ビット)、H(0.1)は1(ビット)になる。", "pの値によらずH(p)は常に同じ値(1ビット)になり、pを変えても変化しない一定の値である。"]',
   0, '[0]', 'single',
   '{"asked": "2値エントロピーH(p)を、p=0.5とp=0.1という2つの値で実際に計算して比較する。", "point": "H(p)はp=0.5(五分五分)で最大の1になり、0や1に近づくほど小さくなる。", "why_asked": "エントロピーが「どれだけ予測しづらいか(不確実性)」を表す量であることを、p=0.5(一番予測しづらい)とp=0.1(かなり予測しやすい)という具体的な数値で体感させる定番の計算問題。", "kid": "H(p)は「コインの表が出る確率がpのとき、次に表か裏か当てるのがどれだけ難しいか」を表す数。五分五分(p=0.5)が一番当てにくく、極端に偏っている(p=0.1)ほうが当てやすい。", "eg": "五分五分の勝負(p=0.5)は次にどちらが勝つか予想しづらいが、10回に1回しか勝たない勝負(p=0.1)は「たぶん負ける」とほぼ言い当てられる。当てやすさの違いがそのままエントロピーの大小になる。", "terms": [["2値エントロピー", "結果が2通りしかない事象の「予測しづらさ」を表す量。確率pの関数として計算する"], ["log2(対数、底2)", "2を何乗するとその数になるかを表す。ビット単位でエントロピーを測るときに使う"]], "think": "H(p)はp=0.5のときに最大値1を取り、pが0や1に近づくほど(どちらかの結果がほぼ確定するほど)小さくなる。p=0.1のように結果が偏っていると「たぶんこっちだろう」と予測しやすくなるため、エントロピー(予測しづらさ)は下がる。", "calc": {"steps": ["問題: H(p) = -p log2(p) - (1-p) log2(1-p) をp=0.5とp=0.1で計算する", "ステップ1: p=0.5のとき。-0.5×log2(0.5) - 0.5×log2(0.5) = -0.5×(-1) - 0.5×(-1) = 0.5+0.5 = 1", "ステップ2: p=0.1のとき、-p log2(p)の項。-0.1×log2(0.1) ≈ -0.1×(-3.32) = 0.332", "ステップ3: p=0.1のとき、-(1-p) log2(1-p)の項。-0.9×log2(0.9) ≈ -0.9×(-0.152) = 0.137", "ステップ4: 2つの項を足す。0.332 + 0.137 ≈ 0.469", "答え: H(0.5)=1(ビット)、H(0.1)は約0.47(ビット)で、p=0.5のほうが大きい"], "formula": "H(p) = -p log2(p) - (1-p) log2(1-p)"}, "vs": "分類問題のクロスエントロピー損失は、この2値エントロピーの考え方を「正解ラベルとモデルの予測確率」の関係に拡張したもの。ここでのH(p)は分布そのものの予測しづらさを表す点が異なる。", "opt": ["正解。H(0.5)=0.5×1+0.5×1=1、H(0.1)≈0.332+0.137≈0.47で、p=0.5のほうが大きい。", "p=0.5とp=0.1のどちらが大きいかが逆になっており、値も1.5という2値エントロピーの最大値(1)を超える数値になっている。", "p=0.5のほうが大きいという大小関係は正しいが、H(0.5)とH(0.1)の具体的な数値が入れ替わっている。", "2値エントロピーはpの値によって変化する量であり、p=0.5のときに最大値1を取り、pが0や1に近づくと値は小さくなる。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">2値エントロピーH(p)はp=0.5で最大になる</text><line x1=\"40\" y1=\"110\" x2=\"300\" y2=\"110\" stroke=\"#2a2f3f\"/><line x1=\"40\" y1=\"110\" x2=\"40\" y2=\"30\" stroke=\"#2a2f3f\"/><text x=\"30\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">H(p)</text><text x=\"300\" y=\"124\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">p</text><path d=\"M42,108 Q90,45 170,35 Q250,45 298,108\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><circle cx=\"170\" cy=\"35\" r=\"3.5\" fill=\"#e8eaf0\"/><text x=\"170\" y=\"24\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">p=0.5 → H=1</text><circle cx=\"66\" cy=\"68\" r=\"3.5\" fill=\"#c9a04a\"/><text x=\"66\" y=\"86\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">p=0.1 → H≈0.47</text></svg>"}'),

  ('e-shikaku-b-q54', '1. 数学的基礎',
   '分類モデルの学習でクロスエントロピー損失を最小化することは、なぜ最尤推定(尤度を最大化すること)と同じことになるのか。その理由として正しいものはどれか。',
   NULL::text,
   '["分類モデルの予測確率で尤度を書くと、対数尤度の符号を反転したものがクロスエントロピー損失の式とちょうど一致するため、最小化は対数尤度の最大化と同じ操作になる。", "クロスエントロピーと対数尤度は式の形も意味も別物だが、多くのデータセットで最小化した結果の値がたまたま近くなるという経験的な性質があるため、同じ操作として扱われている。", "クロスエントロピーは尤度そのものと常に同じ値を返す関数として定義されているため、クロスエントロピーを最小化することが自動的に尤度の最大化と同じ計算になる。", "クロスエントロピーを最小化すると学習が必ず速く終わるという経験則があり、計算コストの都合で最尤推定の代わりに使われているだけで、理論的なつながりはない。"]',
   0, '[0]', 'single',
   '{"asked": "クロスエントロピー損失の最小化が、なぜ最尤推定と数学的に同じ操作になるのか。", "point": "対数尤度に符号を反転させると、そのままクロスエントロピー損失の式になる。", "why_asked": "クロスエントロピーの数値計算はできても、それを最小化することがなぜ最尤推定と同じなのか(理論的な根拠)を問われると答えられない、という理解の抜けを狙った定番論点。", "kid": "「クロスエントロピーを小さくする」という作業は、実は「データがいかにも起こりそうだと思えるようにモデルを調整する(尤度を大きくする)」という作業と、符号がひっくり返っているだけで中身は同じもの。", "eg": "同じ坂道を「頂上までの高さ」で測るか「頂上からの深さ(マイナスの高さ)」で測るかの違いのようなもの。頂上を目指す(尤度を最大化する)のと、深さを最小にする(クロスエントロピーを最小化する)のは、同じ坂道を上っているだけで結果は同じ場所にたどり着く。", "terms": [["負の対数尤度", "対数尤度にマイナスを付けたもの。最大化ではなく最小化の問題として扱うために使う"], ["クロスエントロピー損失", "正解ラベルとモデルの予測確率のズレを測る損失関数。-Σy log(p)の形で書かれる"]], "think": "分類モデルの出力確率をパラメータとして尤度を書くと、独立な複数データの尤度は各データの予測確率の積になる。対数を取ると和になり(既出の対数尤度と同じ理屈)、さらに符号を反転させたもの(負の対数尤度)が、正解ラベルとの重み付き和として書いたクロスエントロピー損失の式とちょうど同じ形になる。そのため「クロスエントロピーを最小化する」ことと「対数尤度を最大化する(最尤推定を行う)」ことは同じ最適化問題になる。", "calc": {"steps": ["問題: 1つのデータで正解ラベルy=1、モデルの予測確率p=0.8とする", "ステップ1: このデータの尤度はモデルの予測確率そのまま。L = 0.8", "ステップ2: 対数尤度を求める。log(0.8) ≈ -0.223", "ステップ3: 符号を反転する(負の対数尤度)。-log(0.8) ≈ 0.223", "ステップ4: クロスエントロピー損失 -y log(p) - (1-y) log(1-p) にy=1, p=0.8を入れると、後半の項は0になり -log(0.8) ≈ 0.223 と一致する", "答え: 負の対数尤度とクロスエントロピー損失は同じ0.223になる(符号を反転させた対数尤度=クロスエントロピー)"], "formula": "クロスエントロピー損失 = -対数尤度 = -Σ [y log(p) + (1-y) log(1-p)]"}, "vs": "既存のKLダイバージェンスとの関係(クロスエントロピー=エントロピー+KLダイバージェンス)は「クロスエントロピー自体が何を表すか」の話であるのに対し、ここでの論点は「クロスエントロピーの最小化がなぜ最尤推定と一致するか」という最適化の同値性の話であり、問うている角度が異なる。", "opt": ["正解。対数尤度の符号を反転させた式がクロスエントロピー損失の式そのものと一致するため、最小化と最大化が同じ最適化問題になる。", "クロスエントロピーと対数尤度は数式のレベルで符号を反転させただけの関係にあり、値が近くなるのは偶然の経験則ではない。", "クロスエントロピーは尤度(0から1の確率の値)そのものと同じ値を返す関数ではなく、対数を取って符号を反転させた値を返す関数である。", "クロスエントロピーの最小化と最尤推定が同じ操作になるのは学習速度の経験則ではなく、対数尤度との数式的な一致による理論的な関係である。"]}')

